/**
 * 回路关注共享状态（P6-05 关注入口断链修复）
 *
 * 修复背景：follow API（PUT /me/loop-follows/{loopId}）此前前端零调用，
 * 用户无法从任何界面发起关注，「我的关注」视图结构性为空。本 composable
 * 为三个入口（回路监视列表星标 / wb360 页头星标 / 我的工作-我的关注）
 * 提供同一份关注集与切换动作，复用 api/personal-work.ts 既有封装，
 * 不分叉第二套实现。
 *
 * 后端契约（personal_workspace.py，树内源码即事实）：
 * - GET /me/loop-follows 仅返回本人已关注且可访问回路（分页，pageSize≤100）
 *   ——未在清单中的回路视为未关注（含"关注后又取消"的墓碑行）；
 * - PUT 设定语义非 toggle：首次创建（含墓碑复活）expectedRevision 失配即
 *   409，携 {currentRevision, isFollowed}；同 requestId 幂等重放；
 * - 取消关注保留版本墓碑，取消后迟到的旧关注请求（旧版本号或
 *   expectedRevision=0）均 409，不得复活。
 *
 * 客户端纪律（01a §2.1/§3）：乐观更新仅在服务端确认后保留；失败回滚；
 * 409 按冲突载荷收敛——服务端已是目标状态视为幂等成功，否则以
 * currentRevision 重试一次，再冲突则以服务端真实状态回滚并如实提示。
 */
import { computed, reactive, readonly, ref } from 'vue';

import { message } from 'ant-design-vue';

import {
  extractRevisionConflict,
  getMyLoopFollowsApi,
  newRequestId,
  setLoopFollowApi,
} from '#/api/personal-work';

/* ── 模块级状态（全应用共享一份：监视列表/wb360 页头/我的工作同一关注集；
先例 use-clpm-preferences 同款模块级单例模式） ── */

/** loopId → 当前已知 revision（仅关注中的回路；未关注视为 0/未知） */
const followed = reactive(new Map<string, number>());
/** 关注集读取状态：idle=未读取 loading/ready/error（error 时星标初始态不可信，如实提示） */
const loadState = ref<'error' | 'idle' | 'loading' | 'ready'>('idle');
/** 单回路切换在途（防同回路重入；其他回路不受影响） */
const busy = reactive(new Set<string>());
/** 并发去重：读取在途时后续调用复用同一 Promise */
let loadPromise: null | Promise<boolean> = null;

const LIST_PAGE_SIZE = 100; // 后端上限（Query le=100）

export interface FollowToggleOutcome {
  /** 重试一次后仍冲突：附服务端当前关注态（UI 如实提示"已在别处变更"） */
  conflict?: { isFollowed: boolean | null };
  ok: boolean;
}

/** 拉取关注集全量（分页循环）；force=false 且已就绪时零请求直接返回 */
export function refreshFollows(force = false): Promise<boolean> {
  if (!force && loadState.value === 'ready') return Promise.resolve(true);
  if (loadPromise) return loadPromise;
  loadState.value = 'loading';
  loadPromise = (async () => {
    try {
      const next = new Map<string, number>();
      let page = 1;
      for (;;) {
        const data = await getMyLoopFollowsApi({
          page,
          pageSize: LIST_PAGE_SIZE,
        });
        for (const it of data.items) next.set(it.loopId, it.revision);
        const size = data.pageSize || LIST_PAGE_SIZE;
        if (page >= Math.max(1, Math.ceil(data.total / size))) break;
        page += 1;
      }
      followed.clear();
      for (const [id, rev] of next) followed.set(id, rev);
      loadState.value = 'ready';
      return true;
    } catch {
      loadState.value = 'error';
      return false;
    } finally {
      loadPromise = null;
    }
  })();
  return loadPromise;
}

function applyLocal(loopId: string, isFollowed: boolean, revision: number) {
  if (isFollowed) followed.set(loopId, revision);
  else followed.delete(loopId);
}

/**
 * 关注状态切换（乐观更新 + 失败回滚 + 409 收敛）。
 * @param loopId 回路 ID
 * @param label 提示文案中的位号（可选，缺省"该回路"）
 */
export async function toggleLoopFollow(
  loopId: string,
  label: null | string = '该回路',
): Promise<FollowToggleOutcome> {
  const name = label;
  if (busy.has(loopId)) return { ok: false };
  busy.add(loopId);
  const wasFollowed = followed.has(loopId);
  const knownRevision = followed.get(loopId);
  const target = !wasFollowed;

  // 乐观更新：服务端确认后以返回 revision 收敛；失败路径回滚（占位 0 不外泄）
  applyLocal(loopId, target, 0);

  const request = (revision: number) =>
    setLoopFollowApi(loopId, {
      expectedRevision: revision,
      isFollowed: target,
      requestId: newRequestId(),
    });

  try {
    const result = await request(knownRevision ?? 0);
    applyLocal(loopId, result.isFollowed, result.revision);
    message.success(target ? `已关注 ${name}` : `已取消关注 ${name}`);
    return { ok: true };
  } catch (error) {
    const conflict = extractRevisionConflict(error);
    if (!conflict) {
      // 网络/5xx（setLoopFollowApi skipErrorMessage：全局不弹，由这里提示）
      applyLocal(loopId, wasFollowed, knownRevision ?? 0);
      message.error(target ? `关注 ${name} 失败，请重试` : `取消关注 ${name} 失败，请重试`);
      return { ok: false };
    }
    // 幂等收敛：服务端已是目标状态（他处已操作/同义重放）→ 按成功口径对齐
    if (conflict.isFollowed === target) {
      applyLocal(loopId, target, conflict.currentRevision ?? 0);
      message.success(target ? `已关注 ${name}` : `已取消关注 ${name}`);
      return { ok: true };
    }
    // 版本失配（如本地 revision 过期/墓碑复活）：以服务端当前版本重试一次
    try {
      const retry = await request(conflict.currentRevision ?? 0);
      applyLocal(loopId, retry.isFollowed, retry.revision);
      message.success(target ? `已关注 ${name}` : `已取消关注 ${name}`);
      return { ok: true };
    } catch (retryError) {
      const c2 = extractRevisionConflict(retryError);
      // 以服务端真实状态回滚（不保留乐观假态），如实提示
      const serverFollowed = c2?.isFollowed ?? wasFollowed;
      applyLocal(loopId, serverFollowed, c2?.currentRevision ?? knownRevision ?? 0);
      message.warning(`关注状态已在其他页面变更，已按当前状态（${
        serverFollowed ? '已关注' : '未关注'
      }）刷新`);
      return { conflict: { isFollowed: c2?.isFollowed ?? null }, ok: false };
    }
  } finally {
    busy.delete(loopId);
  }
}

/** 重置模块级状态（测试隔离用） */
export function resetLoopFollowState(): void {
  followed.clear();
  busy.clear();
  loadState.value = 'idle';
  loadPromise = null;
}

/** 回路关注共享集访问器（三入口共用；状态本身为模块级单例） */
export function useLoopFollow() {
  return {
    /** 关注集读取状态（error=初始态不可信，入口应如实提示） */
    followLoadState: readonly(loadState),
    /** 当前关注回路 ID 集（快照；UI 响应式判定用 isFollowed） */
    followedLoopIds: computed(() => new Set(followed.keys())),
    /** ensureLoaded：未就绪时拉取一次（入口 onMounted 调用；失败返回 false） */
    ensureLoaded: () => refreshFollows(false),
    isBusy: (loopId: string) => busy.has(loopId),
    isFollowed: (loopId: string) => followed.has(loopId),
    refresh: () => refreshFollows(true),
    toggle: toggleLoopFollow,
  };
}

import type { Recordable, UserInfo } from '@vben/types';

import { ref } from 'vue';
import { useRouter } from 'vue-router';

import { LOGIN_PATH } from '@vben/constants';
import { preferences } from '@vben/preferences';
import { resetAllStores, useAccessStore, useUserStore } from '@vben/stores';

import { notification } from 'ant-design-vue';
import { defineStore } from 'pinia';

import { getAccessCodesApi, getUserInfoApi, loginApi, logoutApi } from '#/api';
import { $t } from '#/locales';
import { setGrantedPageCodes } from '#/router/routes';

/**
 * 角色默认首页（实现契约 §5 + UI/UX §4.2 三方对齐基准 + 方案 11 §3.1）
 *
 * FP-P0-08：后端 auth.py ROLE_DEFAULT_HOME 已对齐本表，事实源统一。
 * 角色映射优先于后端 defaultHome 返回值（双保险），二者口径一致。
 *
 * - 2026-10-14 P6-06（IAR-D1/D2）：工程师（IC/PE/EXPERT）首页为我的工作
 *   /my-work；管理员/观察者（ADMIN/SPONSOR）为驾驶舱 /cockpit。
 *   个人 default_home 偏好（/me/workspace-preferences，合法站内路径）优先
 *   于本角色默认——见 resolveUserHomePath。
 */
const ROLE_DEFAULT_HOME: Record<string, string> = {
  ADMIN: '/cockpit',
  EXPERT: '/my-work',
  IC_ENGINEER: '/my-work',
  PE_ENGINEER: '/my-work',
  SPONSOR: '/cockpit',
};

/**
 * 计算用户默认首页：前端角色映射优先，回退后端 defaultHome，最终兜底 /cockpit
 */
function resolveHomePath(
  role: string,
  backendDefaultHome?: null | string,
): string {
  return ROLE_DEFAULT_HOME[role] ?? backendDefaultHome ?? '/cockpit';
}

/**
 * 登录/首页解析（F-G2 default_home 消费链）：个人 default_home 偏好（服务端
 * 持久、合法站内路径）优先于角色映射；加载失败/无偏好/非法值回退角色映射，
 * **不阻断登录**。
 *
 * 时序：登录令牌与用户信息就绪后、router.push 前读取（避免"先跳角色首页
 * 再替换"的闪烁）；路径合法性经 isValidHomePath 双端校验，越权路径由路由
 * 守卫按既有口径兜底（与书签/旧链接一致）。
 */
async function resolveUserHomePath(
  role: string,
  backendDefaultHome?: null | string,
): Promise<string> {
  const roleHome = resolveHomePath(role, backendDefaultHome);
  try {
    const { fetchDefaultHomePreference, isValidHomePath } = await import(
      '#/composables/use-clpm-preferences'
    );
    const preferred = await fetchDefaultHomePreference();
    return preferred && isValidHomePath(preferred) ? preferred : roleHome;
  } catch {
    return roleHome;
  }
}

export { resolveHomePath, resolveUserHomePath, ROLE_DEFAULT_HOME };

export const useAuthStore = defineStore('auth', () => {
  const accessStore = useAccessStore();
  const userStore = useUserStore();
  const router = useRouter();

  const loginLoading = ref(false);

  /**
   * 异步处理登录操作（对齐 IDS v3.2 §5.1）
   * @param params 登录表单数据（username, password, rememberMe）
   * @param onSuccess 登录成功回调（可选）
   */
  async function authLogin(
    params: Recordable<any>,
    onSuccess?: () => Promise<void> | void,
  ) {
    let userInfo: null | UserInfo = null;
    try {
      loginLoading.value = true;

      // 1. 调用登录接口，获取 accessToken + refreshToken + 基础用户信息
      const loginResult = await loginApi({
        password: params.password,
        rememberMe: params.rememberMe ?? false,
        username: params.username,
      });

      const { accessToken, refreshToken, user: loginUser } = loginResult;

      if (accessToken) {
        // 2. 存储 accessToken 和 refreshToken（持久化到 localStorage）
        accessStore.setAccessToken(accessToken);
        accessStore.setRefreshToken(refreshToken);

        // 3. 获取完整用户信息（/auth/me），包含 permissions/pageCodes/defaultHome
        //    P4-02：permissions=动作码（按钮显隐）、pageCodes=页面码（菜单可达页）
        //    均由后端 DB 授权矩阵下发（显式码，无通配）
        const [currentUser, accessCodes] = await Promise.all([
          getUserInfoApi(),
          fetchAccessCodes(loginUser.permissions),
        ]);

        // 页面码写入路由表模块（守卫在 generateAccess 前消费）
        setGrantedPageCodes(currentUser.pageCodes ?? []);

        // 4. 转换为框架 UserInfo 并存储（首页：个人 default_home 偏好优先于
        //    角色映射；router.push 前解析完毕，无闪烁）
        userInfo = {
          avatar: '',
          desc: currentUser.email,
          homePath: await resolveUserHomePath(
            currentUser.role,
            currentUser.defaultHome,
          ),
          realName: currentUser.displayName,
          roles: [currentUser.role],
          token: accessToken,
          userId: currentUser.id,
          username: currentUser.username,
        };

        userStore.setUserInfo(userInfo);
        accessStore.setAccessCodes(accessCodes);

        // P6-06：登记本次登录稳定用户 ID——与上次登录不同（换账号）时清理
        // 本部署账户维度偏好缓存（上一个人的内容不能展示给下一个人）。
        // 动态 import 避免 auth → composables → api/request → store 初始化环。
        try {
          const { noteClpmAccountLogin } = await import(
            '#/composables/use-clpm-preferences'
          );
          noteClpmAccountLogin(String(currentUser.id));
        } catch {
          /* 缓存清理失败不阻断登录 */
        }

        // 5. 跳转首页或回调
        if (accessStore.loginExpired) {
          accessStore.setLoginExpired(false);
        } else {
          await (onSuccess
            ? onSuccess()
            : router.push(
                userInfo.homePath || preferences.app.defaultHomePath,
              ));
        }

        if (userInfo?.realName) {
          notification.success({
            description: `${$t('authentication.loginSuccessDesc')}:${userInfo?.realName}`,
            duration: 3,
            message: $t('authentication.loginSuccess'),
          });
        }
      }
    } finally {
      loginLoading.value = false;
    }

    return {
      userInfo,
    };
  }

  /**
   * 获取权限码
   * 优先使用登录返回的 permissions，若为空则回退到 /auth/codes 接口
   */
  async function fetchAccessCodes(permissions?: string[]): Promise<string[]> {
    if (permissions && permissions.length > 0) {
      return permissions;
    }
    try {
      return await getAccessCodesApi();
    } catch {
      return [];
    }
  }

  /**
   * 登出（对齐 IDS v3.2 §5.3）
   * 清空 Store + localStorage，跳转登录页
   *
   * - 仅在 accessToken 有效时调用后端 logout（黑名单 token）
   * - doReAuthenticate 触发登出时 token 已被清空，跳过后端调用避免 401 循环
   * - 增加 isLoggingOut CAS 锁，防止手动登出与 401 拦截器登出并发执行
   * - 状态清理与路由跳转统一放在 finally，失败场景下跳转必达（fail-safe）
   */
  async function logout(redirect: boolean = true) {
    const accessStore = useAccessStore();
    // CAS：已在登出流程中则直接返回，避免 resetAllStores / router.replace 竞争
    if (accessStore.isLoggingOut) {
      return;
    }
    accessStore.setIsLoggingOut(true);
    // 快照当前 token 与当前页面 fullPath，避免清理动作之后的读值不一致
    const hasToken = Boolean(accessStore.accessToken);
    const currentFullPath = router.currentRoute.value.fullPath;
    try {
      if (hasToken) {
        try {
          await logoutApi();
        } catch {
          // logout 接口失败（401 / 403 / 断网）不阻断本地登出
        }
      }
    } finally {
      try {
        resetAllStores();
      } catch {
        // 兜底：resetAllStores 若抛错，手动清 token，避免守卫反弹回首页
        accessStore.setAccessToken(null);
        accessStore.setRefreshToken(null);
        accessStore.setAccessCodes([]);
        try {
          useUserStore().setUserInfo(null);
        } catch {
          /* noop */
        }
      }
      accessStore.setLoginExpired(false);
      accessStore.setIsLoggingOut(false);
      // P6-06：退出清理账户维度偏好缓存与模块状态（服务端数据不受影响；
      // 换设备/换账号/清理浏览器后由服务端恢复，不在本机残留上一个人内容）。
      try {
        const { handleClpmAccountLogout } = await import(
          '#/composables/use-clpm-preferences'
        );
        handleClpmAccountLogout();
      } catch {
        /* 缓存清理失败不阻断登出 */
      }
      const targetQuery = redirect
        ? { redirect: encodeURIComponent(currentFullPath) }
        : {};
      try {
        await router.replace({ path: LOGIN_PATH, query: targetQuery });
      } catch {
        // Vue Router 中断或守卫抛错时兜底硬跳转，保证登出必达
        const qs =
          redirect && currentFullPath
            ? `?redirect=${encodeURIComponent(currentFullPath)}`
            : '';
        window.location.replace(`${LOGIN_PATH}${qs}`);
      }
    }
  }

  /**
   * 获取用户信息（对齐 IDS v3.2 §5.4）
   * 用于路由守卫中按需刷新用户信息
   */
  async function fetchUserInfo() {
    const currentUser = await getUserInfoApi();
    const userInfo: UserInfo = {
      avatar: '',
      desc: currentUser.email,
      homePath: await resolveUserHomePath(
        currentUser.role,
        currentUser.defaultHome,
      ),
      realName: currentUser.displayName,
      roles: [currentUser.role],
      token: accessStore.accessToken || '',
      userId: currentUser.id,
      username: currentUser.username,
    };
    userStore.setUserInfo(userInfo);
    accessStore.setAccessCodes(currentUser.permissions || []);
    // P4-02：页面码随用户信息刷新（守卫菜单过滤消费；无值时不过滤=旧后端兼容）
    setGrantedPageCodes(currentUser.pageCodes ?? []);
    return userInfo;
  }

  function $reset() {
    loginLoading.value = false;
  }

  return {
    $reset,
    authLogin,
    fetchUserInfo,
    loginLoading,
    logout,
  };
});

/**
 * 工程模板维护页纯函数（P6 Slice M）
 *
 * 与组件解耦的可单测逻辑：
 * - profile 版本差异计算（版本详情与差异 / 发布预览「与当前版本差异」）
 * - 发布流程状态机（dry-run → 确认 → 真实发布 → 结果；模板版本发布 /
 *   覆盖发布 / 批量应用三向导共用）
 * - 批量回路分批（后端单批 loopIds ≤ 200 的客户端顺序分批）
 * - 批量结果汇总与状态标签（成功/失败项逐条呈现）
 * - 诚实化口径：清单截断提示（仅显示前 N 条（共 M 条））
 */

// ===========================================================================
// profile 版本差异
// ===========================================================================

export type ProfileDiffKind = 'added' | 'changed' | 'removed' | 'unchanged';

export interface ProfileDiffEntry {
  key: string;
  kind: ProfileDiffKind;
  before: unknown;
  after: unknown;
}

/** 值相等判定（JSON 序列化比较；profile 为服务端 JSONB 自由档案） */
function profileValueEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch {
    return false;
  }
}

/**
 * 计算两版本 profile 的键级差异（键并集按字典序排列）。
 *
 * before=null（首版发布/无基线）时全部键为 added；after=null 时全部 removed。
 */
export function diffProfileEntries(
  before: null | Record<string, any> | undefined,
  after: null | Record<string, any> | undefined,
): ProfileDiffEntry[] {
  const b = before ?? {};
  const a = after ?? {};
  const keys = [...new Set([...Object.keys(b), ...Object.keys(a)])].toSorted();
  return keys.map((key) => {
    const inBefore = Object.prototype.hasOwnProperty.call(b, key);
    const inAfter = Object.prototype.hasOwnProperty.call(a, key);
    if (!inBefore) return { key, kind: 'added', before: undefined, after: a[key] };
    if (!inAfter) return { key, kind: 'removed', before: b[key], after: undefined };
    return profileValueEqual(b[key], a[key])
      ? { key, kind: 'unchanged', before: b[key], after: a[key] }
      : { key, kind: 'changed', before: b[key], after: a[key] };
  });
}

/** 非 unchanged 的差异条数（「与当前版本相比 N 项变化」口径） */
export function countProfileChanges(entries: ProfileDiffEntry[]): number {
  return entries.filter((e) => e.kind !== 'unchanged').length;
}

export const PROFILE_DIFF_LABEL: Record<ProfileDiffKind, string> = {
  added: '新增',
  removed: '移除',
  changed: '变更',
  unchanged: '不变',
};

// ===========================================================================
// 发布流程状态机（dry-run → 确认 → 真实发布 → 结果）
// ===========================================================================

/**
 * 状态：
 * - edit：编辑参数/档案
 * - previewing：dry-run 预览请求中
 * - previewed：预览就绪（校验/差异/影响范围可见），可返回编辑或确认发布
 * - publishing：真实发布请求中（不可再编辑）
 * - done：发布成功（展示 revision/revisionRef/affectedLoops 与回退引用）
 * - failed：发布失败（含 409 冲突；可重新预览或重试）
 */
export type PublishFlowStep =
  | 'done'
  | 'edit'
  | 'failed'
  | 'previewed'
  | 'previewing'
  | 'publishing';

export type PublishFlowEvent =
  | 'BACK_TO_EDIT'
  | 'CONFIRM_PUBLISH'
  | 'PREVIEW_ERROR'
  | 'PREVIEW_OK'
  | 'PUBLISH_ERROR'
  | 'PUBLISH_OK'
  | 'RESET'
  | 'START_PREVIEW';

const FLOW_TRANSITIONS: Record<
  PublishFlowStep,
  Partial<Record<PublishFlowEvent, PublishFlowStep>>
> = {
  edit: { START_PREVIEW: 'previewing' },
  previewing: { PREVIEW_OK: 'previewed', PREVIEW_ERROR: 'edit' },
  previewed: {
    BACK_TO_EDIT: 'edit',
    START_PREVIEW: 'previewing',
    CONFIRM_PUBLISH: 'publishing',
  },
  publishing: { PUBLISH_OK: 'done', PUBLISH_ERROR: 'failed' },
  failed: {
    BACK_TO_EDIT: 'edit',
    START_PREVIEW: 'previewing',
    CONFIRM_PUBLISH: 'publishing',
  },
  done: { RESET: 'edit' },
};

/**
 * 状态迁移（非法迁移保持原态——调用方据此判断按钮可用性，
 * 保证「未预览不得发布」这一硬约束在 UI 层不可绕过）。
 */
export function reducePublishFlow(
  step: PublishFlowStep,
  event: PublishFlowEvent,
): PublishFlowStep {
  return FLOW_TRANSITIONS[step][event] ?? step;
}

/** 是否可发起 dry-run 预览 */
export function canPreview(step: PublishFlowStep): boolean {
  return step === 'edit' || step === 'previewed' || step === 'failed';
}

/** 是否可确认真实发布（必须先完成 dry-run 预览） */
export function canConfirmPublish(step: PublishFlowStep): boolean {
  return step === 'previewed' || step === 'failed';
}

// ===========================================================================
// 批量应用：分批 / 汇总 / 状态呈现
// ===========================================================================

/** 后端单批 loopIds 上限（schemas/loop_batch.py max_length=200 防线） */
export const BATCH_LOOP_IDS_LIMIT = 200;

/**
 * 千回路路径：客户端顺序分批（每批 ≤ 200，逐批 dry-run → 确认 → 执行）。
 * 容量实证归 P5-05/G5-D02（本页显式提示该口径，不虚称已验证）。
 */
export function chunkLoopIds(
  loopIds: string[],
  size = BATCH_LOOP_IDS_LIMIT,
): string[][] {
  const safeSize = Math.max(1, Math.min(size, BATCH_LOOP_IDS_LIMIT));
  const chunks: string[][] = [];
  for (let i = 0; i < loopIds.length; i += safeSize) {
    chunks.push(loopIds.slice(i, i + safeSize));
  }
  return chunks;
}

export interface BatchSummary {
  total: number;
  ok: number;
  unchanged: number;
  failed: number;
  notFound: number;
  /** 实际应用/将应用数（OK 条目数，与后端 affected 同口径） */
  affected: number;
}

/** 逐条结果汇总（成功/失败项计数；跨分批合并口径） */
export function summarizeBatchResults(
  items: { status: 'FAIL' | 'NOT_FOUND' | 'OK' | 'UNCHANGED' }[],
): BatchSummary {
  const summary: BatchSummary = {
    total: items.length,
    ok: 0,
    unchanged: 0,
    failed: 0,
    notFound: 0,
    affected: 0,
  };
  for (const item of items) {
    switch (item.status) {
    case 'FAIL': {
      summary.failed += 1;

    break;
    }
    case 'NOT_FOUND': {
      summary.notFound += 1;

    break;
    }
    case 'OK': {
      summary.ok += 1;
      summary.affected += 1;

    break;
    }
    case 'UNCHANGED': {
      summary.unchanged += 1;

    break;
    }
    // No default
    }
  }
  return summary;
}

export const BATCH_STATUS_LABEL: Record<
  'FAIL' | 'NOT_FOUND' | 'OK' | 'UNCHANGED',
  string
> = {
  OK: '成功',
  UNCHANGED: '无变化',
  FAIL: '失败',
  NOT_FOUND: '不存在',
};

